import React, { useEffect, useState } from "react";
import { API } from "../config";

export default function UserPanel({ userId }) {
  const [challans, setChallans] = useState([]);

  const fetchMine = async () => {
    const res = await fetch(`${API}/challan/user/${userId}`);
    const data = await res.json();
    setChallans(data);
  };

  const pay = async (id) => {
    const res = await fetch(`${API}/challan/pay/${id}`, { method: "POST" });
    const data = await res.json();
    alert(data.message || "Paid");
    fetchMine();
  };

  useEffect(() => {
    fetchMine();
  }, []);

  return (
    <div>
      <h3>My Challans</h3>
      <button onClick={fetchMine}>Refresh</button>
      <table border="1" cellPadding="6">
        <thead>
          <tr>
            <th>#</th>
            <th>Vehicle</th>
            <th>Cause</th>
            <th>Fine</th>
            <th>Status</th>
            <th>Action</th>
          </tr>
        </thead>
        <tbody>
          {challans.map((c, i) => (
            <tr key={c._id}>
              <td>{i + 1}</td>
              <td>{c.vehicleNumber}</td>
              <td>{c.cause}</td>
              <td>{c.fine}</td>
              <td>{c.status}</td>
              <td>{c.status !== "Paid" && <button onClick={() => pay(c._id)}>Pay</button>}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
